import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:ital,wght@0,400;0,600;0,700;1,400;1,700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type OnscreenGraphicProps = Record<string, any>;

const OnscreenGraphic: React.FC<OnscreenGraphicProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 5,
  imitateText = "Imitate",
  bridgeText = "and then",
  innovateText = "Innovate.",
  imitateColor = "#888888",
  bridgeColor = "#555555",
  innovateColor = "#ffffff",
  innovateGlowColor = "#ff3366",
  fontSizeBase = 120,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter", "Playfair Display"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive dimensions
  const s = Math.min(width, height);
  const paddingX = width * 0.1;

  // Timings & Physics
  const imitateStart = 10;
  const bridgeStart = 35;
  const innovateStart = 65;

  const imitateSpring = spring({
    frame: Math.max(0, frame - imitateStart),
    fps,
    config: { damping: 14, stiffness: 120 },
  });

  const bridgeOpacity = interpolate(
    frame,
    [bridgeStart, bridgeStart + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const bridgeY = interpolate(
    frame,
    [bridgeStart, bridgeStart + 20],
    [20, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const innovateSpring = spring({
    frame: Math.max(0, frame - innovateStart),
    fps,
    config: { damping: 10, stiffness: 90, mass: 1.2 },
  });

  const innovateGlowOpacity = interpolate(
    frame,
    [innovateStart + 10, innovateStart + 40],
    [0, 0.6],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Layout Shift to create dynamic composition when "Innovate" appears
  const containerShiftX = interpolate(
    innovateSpring,
    [0, 1],
    [0, -width * 0.05]
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", transition: "none" }}>
      
      {/* Background Innovation Glow */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "65%",
          width: s * 0.8,
          height: s * 0.8,
          backgroundColor: innovateGlowColor,
          borderRadius: "50%",
          filter: "blur(150px)",
          transform: `translate(-50%, -50%) scale(${innovateSpring})`,
          opacity: innovateGlowOpacity,
          transition: "none",
          zIndex: 0,
        }}
      />

      {/* Main Content Container */}
      <AbsoluteFill
        style={{
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap: width * 0.02,
          paddingLeft: paddingX,
          paddingRight: paddingX,
          transform: `translateX(${containerShiftX}px)`,
          transition: "none",
          zIndex: 1,
        }}
      >
        {/* Imitate */}
        <div
          style={{
            fontFamily: "Inter",
            fontWeight: 600,
            fontSize: `${fontSizeBase}px`,
            color: imitateColor,
            opacity: interpolate(imitateSpring, [0, 1], [0, 1]),
            transform: `translateY(${interpolate(imitateSpring, [0, 1], [40, 0])}px)`,
            transition: "none",
            letterSpacing: "-0.02em",
          }}
        >
          {imitateText}
        </div>

        {/* Bridge */}
        <div
          style={{
            fontFamily: "Inter",
            fontWeight: 400,
            fontSize: `${fontSizeBase * 0.4}px`,
            color: bridgeColor,
            opacity: bridgeOpacity,
            transform: `translateY(${bridgeY}px)`,
            transition: "none",
            fontStyle: "italic",
            marginTop: fontSizeBase * 0.3, // Baseline alignment adjustment
          }}
        >
          {bridgeText}
        </div>

        {/* Innovate */}
        <div
          style={{
            fontFamily: "Playfair Display",
            fontWeight: 700,
            fontSize: `${fontSizeBase * 1.3}px`,
            color: innovateColor,
            opacity: interpolate(innovateSpring, [0, 0.5], [0, 1]),
            transform: `scale(${interpolate(innovateSpring, [0, 1], [0.8, 1])}) rotate(${interpolate(innovateSpring, [0, 1], [-5, 0])}deg)`,
            transition: "none",
            textShadow: `0px 10px 30px ${innovateGlowColor}80`,
            fontStyle: "italic",
            marginLeft: width * 0.01,
          }}
        >
          {innovateText}
        </div>
      </AbsoluteFill>
      
    </AbsoluteFill>
  );
};

export default OnscreenGraphic;